:root {
  --estado-border: #4E4E4E;
  --estado-text: #202329;
  --estado-light: #F0F0F0;
  --estado-middle: #D7D8DB;
  --estado-base: #BEC0C4;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  border: none;
  background: transparent !important;
  pointer-events: none;
}

.estado-widget,
.estado-widget * {
  box-sizing: border-box;
}

.estado-widget {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: transparent;
  pointer-events: none;
  opacity: var(--w-opacity, 1);
}

.estado-button {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: calc(100% - 4px);
  height: calc(100% - 4px);
  min-width: 0;
  min-height: 0;
  padding: 2px 5px;
  margin: 0;
  overflow: hidden;
  appearance: none;
  border: 2px solid var(--estado-border);
  border-radius: 3px;
  background: linear-gradient(155deg, var(--estado-light), var(--estado-middle) 55%, var(--estado-base));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.75), inset 0 -2px 3px rgba(55,60,69,.14);
  color: var(--estado-text);
  font-family: "Bahnschrift", "DIN Alternate", "Segoe UI", Arial, sans-serif;
  font-size: clamp(12px, 42vmin, 24px);
  font-weight: 700;
  line-height: 1;
  letter-spacing: .015em;
  text-align: center;
  white-space: nowrap;
  cursor: pointer;
  pointer-events: auto;
  user-select: none;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
  transform: translateY(0) scale(1);
  filter: brightness(1);
  transition: filter 130ms ease, transform 110ms ease, box-shadow 110ms ease;
}

.estado-button::after {
  content: "";
  position: absolute;
  inset: 2px 4px auto;
  height: 35%;
  border-radius: 2px 2px 45% 45%;
  background: linear-gradient(rgba(255,255,255,.35), rgba(255,255,255,0));
  pointer-events: none;
  transition: opacity 110ms ease;
}

.estado-text {
  position: relative;
  z-index: 1;
  display: block;
  overflow: hidden;
  max-width: 100%;
  text-overflow: clip;
  pointer-events: none;
}

@media (hover: hover) {
  .estado-button:not(:disabled):hover {
    filter: brightness(.93);
    box-shadow: inset 0 1px 0 rgba(255,255,255,.48), inset 0 -2px 4px rgba(55,60,69,.22);
  }
}

.estado-button:not(:disabled):active {
  transform: translateY(1px) scale(.975);
  filter: brightness(.86);
  box-shadow: inset 0 3px 6px rgba(45,49,58,.35), inset 0 -1px 1px rgba(255,255,255,.28);
}

.estado-button:not(:disabled):active::after { opacity: .18; }
.estado-button:disabled { cursor: default; }
.estado-button:focus-visible { outline: 2px solid #0A638F; outline-offset: -5px; }

.estado-status {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

@media (prefers-reduced-motion: reduce) {
  .estado-button,
  .estado-button::after { transition: none; }
}

