"use strict";

(function () {
  const CONFIRMATION_MS = 8000;
  let button = null;
  let text = null;
  let status = null;
  let latestWidget = null;
  let currentValue = null;
  let pending = null;

  function parseBool(value) {
    if (value === true || value === 1) return true;
    if (value === false || value === 0) return false;
    if (typeof value === "string") {
      const normalized = value.trim().toLowerCase();
      if (normalized === "true" || normalized === "1") return true;
      if (normalized === "false" || normalized === "0") return false;
    }
    return null;
  }

  function canWrite() {
    // PSI CORE habilita este permiso desde Escritura en el Inspector.
    return !!(window.WIDGET && window.WIDGET.escritura) &&
      typeof window.escribir === "function";
  }

  function announce(message) {
    if (status) status.textContent = message;
  }

  function refresh() {
    if (!button || !text) return;

    const label = currentValue === null
      ? "-"
      : currentValue ? "ACTIVA" : "INACTIVA";

    text.textContent = label;
    button.disabled = currentValue === null || !canWrite() || !!pending;
    button.setAttribute("aria-label", currentValue === null
      ? "Sin lectura del PLC"
      : "Estado " + label + ". Pulsar para cambiar");

    if (currentValue === null) button.removeAttribute("aria-pressed");
    else button.setAttribute("aria-pressed", String(currentValue));
  }

  function clearPending() {
    if (!pending) return;
    window.clearTimeout(pending.timer);
    pending = null;
    refresh();
  }

  function render(widget) {
    latestWidget = widget || null;
    currentValue = parseBool(widget && widget.value);

    if (pending && pending.accepted && currentValue === pending.requested) {
      clearPending();
      announce("Estado confirmado: " + (currentValue ? "ACTIVA" : "INACTIVA"));
    }

    refresh();
  }

  window.onWidgetUpdate = render;

  window.onWidgetEscrito = function (response) {
    if (!pending) return;

    if (!response || !response.ok) {
      clearPending();
      announce((response && response.error) || "No se pudo cambiar el estado");
      return;
    }

    pending.accepted = true;
    if (currentValue === pending.requested) {
      clearPending();
      announce("Estado confirmado: " + (currentValue ? "ACTIVA" : "INACTIVA"));
    } else {
      announce("Escritura aceptada. Esperando nueva lectura del PLC");
    }
  };

  function toggle() {
    if (pending || currentValue === null || !canWrite()) return;

    const requested = !currentValue;
    const operation = {
      requested: requested,
      accepted: false,
      timer: window.setTimeout(function () {
        if (pending !== operation) return;
        clearPending();
        announce("El PLC no confirmó el nuevo estado");
      }, CONFIRMATION_MS)
    };

    pending = operation;
    refresh();
    announce("Enviando cambio al PLC");

    try {
      // API de escritura del tag asociado al widget, igual que en el ejemplo.
      window.escribir(requested);
    } catch (error) {
      clearPending();
      announce((error && error.message) || "No se pudo enviar el cambio");
    }
  }

  function initialize() {
    button = document.querySelector(".estado-button");
    text = document.querySelector(".estado-text");
    status = document.querySelector(".estado-status");
    if (!button || !text) return;

    button.addEventListener("click", toggle);
    render(latestWidget || window.WIDGET || null);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initialize, { once: true });
  } else {
    initialize();
  }
})();
